do $$ declare v_pid uuid; v_tid uuid; v_tpl uuid; v_fee uuid; begin

  select tenant_id into v_tid from campus where id='011232d4-269f-595f-bc74-1cb3e0c07b23';
  select id into v_pid from product where campus_id='011232d4-269f-595f-bc74-1cb3e0c07b23' and kind='accommodation' and attributes->>'slug'='oise-oxford-uk-homestay-single-half-board' and coalesce(attributes->>'category','')='' and archived_at is null;
  if v_pid is null then
    insert into product (tenant_id, campus_id, kind, name, source, visibility, status, default_unit, min_duration, max_duration, attributes)
      values (v_tid,'011232d4-269f-595f-bc74-1cb3e0c07b23','accommodation','Casa de família — quarto individual, banheiro compartilhado, meia pensão','supplier','internal','active','week',1,52,'{"seed": "planilha-2026-09", "slug": "oise-oxford-uk-homestay-single-half-board", "category": null, "availability_status": "Pré-confirmado", "link": "https://www.oise.com/uk/destination/linguistic-stay-oxford-4", "supplements": {}}'::jsonb) returning id into v_pid;
    insert into accommodation_detail (product_id, accommodation_type, room_type, bathroom_type, meal_plan) values (v_pid,'homestay','private','shared','half_board');
    insert into product_content (product_id, locale, description_html, highlights, exclusions) values (v_pid,'pt-BR','<p>Homestay da OISE Oxford, a opção mais popular para quem quer viver a rotina autêntica de uma casa britânica durante um curso intensivo. Todos os anfitriões são selecionados com cuidado e as casas visitadas com regularidade; podem ser famílias, casais ou pessoas que moram sozinhas, todas próximas de boas conexões de transporte público para o centro. Inclui quarto individual com área tranquila para estudar e espaço de armazenamento, meia pensão (café da manhã e jantar), Wi-Fi ou acesso à internet, limpeza do quarto e toda a roupa de cama. Não inclui almoço durante a semana, transfer nem passe de ônibus. O aluno costuma receber uma chave e a OISE envia as informações da família (nome, idades dos moradores, endereço, contato e interesses) com pelo menos 5 dias de antecedência. Quartos com banheiro privativo (ensuite ou de uso exclusivo) estão disponíveis mediante taxa adicional, e menores de 18 anos são colocados apenas em famílias com verificação DBS em dia. Nesta opção você fica em quarto individual, com banheiro compartilhado com os demais moradores. O regime é de meia pensão, com café da manhã e jantar inclusos; o almoço fica por sua conta.</p><p>Lista oficial OISE Oxford &quot;Courses for students and professionals - dates and fees 2026&quot;: o homestay em quarto individual com meia pensão (café da manhã e jantar todos os dias) já esta incluído no preço do curso. Quem não precisa de hospedagem deduz GBP 432 por semana do valor do curso, por isso este e o valor semanal registrado. Quartos com banheiro de uso exclusivo existem mediante taxa adicional, cujo valor a OISE não publica. Residências e hotéis sao apenas recomendados pela escola: a reserva e feita diretamente pelo aluno. Chegada no domingo anterior ao início do curso e saída no sábado seguinte ao último dia. Não ha taxa de colocação, suplemento de alta temporada, desconto de baixa temporada, taxa de dieta especial nem caução publicados.</p>','["Quarto Individual", "Área de Estudo no Quarto", "Meia Pensão", "Wi-Fi", "Limpeza do Quarto", "Roupa de Cama Inclusa", "Chave Própria", "Perfil da Família 5 Dias Antes", "Perto de Transporte Público", "Banheiro Privativo sob Taxa", "Famílias com Verificação DBS para Menores", "Banheiro Compartilhado", "Ideal para quem faz curso intensivo e precisa de um lugar calmo para estudar à noite", "Ideal para quem quer imersão autêntica na vida britânica em Oxford", "Ideal para quem prefere ter café da manhã e jantar resolvidos", "Ideal para menores de 18 anos que precisam de um ambiente verificado e seguro", "Ideal para quem quer privacidade no quarto pagando menos que uma suíte", "Ideal para quem não se incomoda em dividir o banheiro", "Ideal para quem quer café da manhã e jantar garantidos e economia no dia a dia"]'::jsonb,'["Menos indicado para quem quer cozinhar e ter horários livres", "Menos indicado para quem precisa de almoço incluso durante a semana", "Menos indicado para quem quer estar a poucos passos da escola sem usar transporte", "Menos indicado para quem tem alergia a animais e não avisa na reserva (parte das casas tem pets)", "Menos indicado para quem faz questão de banheiro exclusivo", "Menos indicado para quem tem horários muito rígidos de banho e rotina", "Menos indicado para quem tem horários irregulares e prefere jantar fora com frequência"]'::jsonb);
  end if;
